import json

EXTRACTION_PROMPT = """Extract the following entities from the text:
- persons, organizations, locations, dates, urls, platforms
Return JSON. Be conservative — only confident entities.

Text: {text}"""

def extract_entities(text: str, llm_client) -> dict:
    prompt = EXTRACTION_PROMPT.format(text=text)
    response = llm_client.chat(prompt)
    try:
        return json.loads(response)
    except json.JSONDecodeError:
        return {'error': 'Parse failed'}

