import requests
from datetime import datetime

def verify_entities(entities: dict) -> dict:
    """Verify extracted entities against real data."""
    verified = entities.copy()
    flagged = []

    # Verify URLs
    for url in entities.get('urls', []):
        try:
            resp = requests.head(url, timeout=5)
            if resp.status_code >= 400:
                flagged.append(f'URL returned {resp.status_code}: {url}')
        except requests.RequestException:
            flagged.append(f'URL unreachable: {url}')

    # Validate dates
    for date_str in entities.get('dates', []):
        try:
            parsed = datetime.strptime(date_str, '%B %d, %Y')
            if parsed > datetime.now():
                flagged.append(f'Future date: {date_str}')
        except ValueError:
            flagged.append(f'Invalid date format: {date_str}')

    verified['verification_flags'] = flagged
    return verified
